static char * scandev_devno_to_devpath ( dev_t devno ) { struct dir_list * list = NULL , * new_list = NULL ; char * devname = NULL ; const char * * dir ; for ( dir = devdirs ; * dir ; dir ++ ) { add_to_dirlist ( * dir , NULL , & list ) ; } while ( list ) { struct dir_list * current = list ; list = list -> next ; DBG ( DEVNO , ul_debug ( "directory %s" , current -> name ) ) ; blkid__scan_dir ( current -> name , devno , & new_list , & devname ) ; free ( current -> name ) ; if ( devname ) { break ; } if ( list == NULL ) { list = new_list ; new_list = NULL ; } } free_dirlist ( & list ) ; free_dirlist ( & new_list ) ; return devname ; } 